from pathlib import Path
import json,subprocess,re,hashlib
W=Path.cwd();D=W/'temp/eval-prep11';B=D/'build';summary=[]
for item in json.loads((D/'build-manifest.json').read_text()):
 if item['object']!='ffmpeg':continue
 label=item['id'];pkgs=B/label
 if not pkgs.exists():continue
 dest=D/'all-elf'/label;dest.mkdir(parents=True,exist_ok=True)
 rpms=[p for p in pkgs.glob('*.rpm') if not any(s in p.name for s in ['-devel-','-debugsource-','.src.rpm'])]
 for rpm in sorted(rpms):
  a=subprocess.Popen(['rpm2cpio',str(rpm)],stdout=subprocess.PIPE)
  b=subprocess.run(['cpio','-idm','--no-absolute-filenames'],stdin=a.stdout,cwd=dest,capture_output=True);a.stdout.close();rc=a.wait()
  if rc or b.returncode:raise RuntimeError((rpm,rc,b.stderr))
 reader=D/'bin'/('a64-readelf' if item['arch']=='aarch64' else 'arm-readelf')
 rows=[]
 for p in sorted((dest/'usr').rglob('*')):
  if p.is_symlink() or not p.is_file() or '/debug/' in str(p):continue
  with p.open('rb') as f:
   if f.read(4)!=b'\x7fELF':continue
  debug=Path(str(dest/'usr/lib/debug'/p.relative_to(dest))+'.debug')
  if not debug.is_file():raise RuntimeError(('missing debug',p))
  row={'runtime':str(p.relative_to(dest)),'debug':str(debug.relative_to(dest))}
  for kind,elf in [('runtime',p),('debug',debug)]:
   result=subprocess.run([str(reader),'-n',str(elf)],capture_output=True,text=True)
   if result.returncode:raise RuntimeError(result.stderr)
   ids=re.findall(r'Build ID: ([a-f0-9]+)',result.stdout)
   if len(ids)!=1 or len(ids[0])!=40:raise RuntimeError((elf,ids))
   row[kind+'_id']=ids[0]
   row[kind+'_sha256']=hashlib.sha256(elf.read_bytes()).hexdigest()
   row[kind+'_readelf']={'command':[str(reader),'-n',str(elf)],'exit':result.returncode,'stdout':result.stdout,'stderr':result.stderr}
  symbols=subprocess.run([str(reader),'-sW',str(debug)],capture_output=True,text=True)
  if symbols.returncode:raise RuntimeError(symbols.stderr)
  symbol_file=dest/(p.name+'.debug.symbols.txt');symbol_file.write_text(symbols.stdout)
  counts={state:len(re.findall(r'\$'+state+r'(?:\.[^\s]+)?\s*$',symbols.stdout,re.M)) for state in ['a','t','d','x']}
  wanted='x' if item['arch']=='aarch64' else 't' if item['isa']=='thumb' else 'a'
  if not counts[wanted]:raise RuntimeError(('missing mapping symbols',debug,counts))
  row['debug_mapping_symbols']=counts
  row['debug_mapping_command']=[str(reader),'-sW',str(debug)]
  row['debug_mapping_raw']=str(symbol_file)
  row['debug_mapping_excerpt']=[line for line in symbols.stdout.splitlines() if re.search(r'\$[atdx](?:\.[^\s]+)?\s*$',line)][:5]
  if row['runtime_id']!=row['debug_id']:raise RuntimeError(('ID mismatch',row))
  rows.append(row)
 summary.append({'id':label,'rpms':[str(p) for p in rpms],'elfs':rows})
 (D/'all-elf-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
 print(label,len(rows),flush=True)
